sys_script_client.script:
function onCellEdit(sysIDs, table, oldValues, newValue, callback) {

    var ga = new GlideAjax('x_hpws_wrkfrcexpam.WrkfrcExpAMAlertUtils');
    ga.addParam('sysparm_name', 'isSingleRecord');

    ga.getXMLAnswer(function(response) {

        var isSingle = (response == 'true');        
        if (isSingle) {
            alert("Only one record exists. You cannot modify Active.");
            callback(false);

        } else {
            callback(true);
        }

    });
}
